import { columnColors } from "../constants/color";
import { Column as ColumnType, Card } from "../types";
import CardItem from "./Card";
import { SortableContext, verticalListSortingStrategy } from "@dnd-kit/sortable";

type Props = {
  index: number;
  column: ColumnType;
  cards: Record<string, Card>;
};

export default function Column({ column, cards, index }: Props) {
  return (
    <div style={{ flex: 1, height: '100%',padding: 10, borderWidth: 3, borderStyle: "solid", borderColor: columnColors[index], borderRadius: 10, display: "flex", flexDirection: "column"  }}>
      <h2 style={{color: columnColors[index]}}>{column.title}</h2>
<SortableContext
  items={column.cardIds}
  strategy={verticalListSortingStrategy}
>
      {column.cardIds.map((id) => (
        <CardItem id={id} key={id} card={cards[id]} />
      ))}

    </SortableContext>
    </div>
  );
}
